import boto3

def stream_platform_generation(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))
    response = client.converse_stream(
        modelId=config.get("model_id", "us.amazon.nova-pro-v1:0"),
        messages=[{"role": "user", "content": [{"text": payload["text"]}]}],
    )
    for chunk in response["body"]:
        if "output" in chunk:
            for content_block in chunk["output"]["message"]["content"]:
                if "text" in content_block:
                    yield {"text": content_block["text"], "raw_response_object": chunk}
        elif "trace" in chunk:
            yield {"trace": chunk["trace"], "raw_response_object": chunk}

import boto3

def collect_platform_metadata(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))
    response = client.converse(
        modelId=config.get("model_id", "us.amazon.nova-pro-v1:0"),
        messages=[{"role": "user", "content": [{"text": payload["text"]}]}],
        inferenceConfig={
            "maxTokens": config.get("max_tokens", 512),
            "temperature": config.get("temperature", 0.5),
        },
    )

    text_output = "".join(block["text"] for block in response["output"]["message"]["content"] if "text" in block)

    metadata = {
        "usage": response.get("usage"),
        "amazon_model_id": response["output"]["responseMetadata"]["modelId"],
        "request_id": response["output"]["responseMetadata"]["requestId"],
        "raw_response_object": response,
    }

    return {"text": text_output, "metadata": metadata}

import boto3
import os

def get_bedrock_client(service_name, region_name=None):
    region = region_name or os.environ.get("AWS_REGION", "us-east-1")
    return boto3.client(service_name, region_name=region)

def get_model_config(model_id=None):
    # In a real application, this might load from a config file or database
    # For this example, we'll use a simple dictionary.
    config = {
        "model_id": model_id or os.environ.get("BEDROCK_MODEL_ID", "us.amazon.nova-pro-v1:0"),
        "region": os.environ.get("AWS_REGION", "us-east-1"),
        "max_tokens": 512,
        "temperature": 0.5,
    }
    return config

class ModelRequest:
    def __init__(self, text: str, parameters: dict = None):
        self.text = text
        self.parameters = parameters or {}

    def to_bedrock_converse_format(self):
        return {"role": "user", "content": [{"text": self.text}]}

class ModelResponse:
    def __init__(self, raw_response: dict):
        self.raw_response = raw_response
        self.text = self._extract_text()
        self.metadata = self._extract_metadata()

    def _extract_text(self):
        if "output" in self.raw_response and "message" in self.raw_response["output"] and "content" in self.raw_response["output"]["message"]:
            return "".join(block["text"] for block in self.raw_response["output"]["message"]["content"] if "text" in block)
        return ""

    def _extract_metadata(self):
        metadata = {
            "usage": self.raw_response.get("usage"),
            "amazon_model_id": self.raw_response["output"]["responseMetadata"]["modelId"] if "output" in self.raw_response and "responseMetadata" in self.raw_response["output"] else None,
            "request_id": self.raw_response["output"]["responseMetadata"]["requestId"] if "output" in self.raw_response and "responseMetadata" in self.raw_response["output"] else None,
        }
        return metadata

import os
from openai import OpenAI

def embed_platform_outputs(text_output):
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
    )

    response = client.embeddings.create(
        input=text_output,
        model="text-embedding-ada-002"
    )

    embedding = response.data[0].embedding

    return {"text": text_output, "embedding": embedding, "model": "text-embedding-ada-002", "provider": "OpenAI"}
